// The Vite configuration of the NgDoc site "docs", generated by
// `ng g @ng-doc/builder:migrate-to-vite` from its legacy build target. The vite-application and
// vite-dev-server targets run it. Edit it freely; the schematic does not overwrite it.
import { createNgDocAngularPlugins } from '@ng-doc/builder/generator/vite/angular/index.js';
import {
  createNgDocApplicationPlugin,
  createNgDocVitePlugin,
} from '@ng-doc/builder/generator/vite/index.js';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const workspaceRoot = fileURLToPath(new URL('../../', import.meta.url));
/** A workspace-relative path as an absolute one. */
const workspace = (file) => path.join(workspaceRoot, file);

/** The settings that differ between the build configurations, by Vite mode. */
const modes = { production: {}, development: { sourcemap: true } };
/** The settings of any other mode: the build target options without a configuration. */
const fallback = {};

export default ({ mode }) => {
  const settings = modes[mode] ?? fallback;
  return {
    base: process.env.DOCS_BASE_HREF ?? '/',
    root: workspace('apps/docs/src'),
    publicDir: false,
    plugins: [
      createNgDocApplicationPlugin({
        workspaceRoot,
        sourceRoot: 'apps/docs/src',
        browser: 'apps/docs/src/main.ts',
        polyfills: ['zone.js'],
        styles: ['apps/docs/src/styles.scss'],
        assets: [
          {
            glob: '**/*',
            input: 'node_modules/@ng-doc/ui-kit/assets',
            output: 'assets/ng-doc/ui-kit',
          },
          { glob: '**/*', input: 'node_modules/@ng-doc/app/assets', output: 'assets/ng-doc/app' },
          { glob: '**/*', input: 'apps/docs/public' },
        ],
      }),
      createNgDocVitePlugin({
        analogLiveReload: true,
        angularPlugins: createNgDocAngularPlugins({
          tsconfig: workspace('apps/docs/tsconfig.app.json'),
          workspaceRoot,
          jit: false,
          disableTypeChecking: false,
          liveReload: true,
          inlineStylesExtension: 'scss',
        }),
        angularComponentProbe: workspace('apps/docs/src/app/app.component.ts'),
        generator: {
          projectId: 'docs',
          workspaceRoot,
          configFile: workspace('apps/docs/ng-doc.vite.config.ts'),
          defaults: {
            docsRoot: workspace('apps/docs/src'),
            tsConfig: workspace('apps/docs/tsconfig.app.json'),
            outputRoot: workspace('ng-doc/docs'),
            cacheRoot: workspace('.cache/ng-doc/docs'),
          },
        },
      }),
    ],
    build: {
      outDir: workspace('dist/apps/docs/browser'),
      emptyOutDir: true,
      sourcemap: settings.sourcemap,
    },
  };
};
